//! `cargo xtask gen`: reference pages generated from the code, so they can't
//! drift from it. `--check` reports pages that are out of date instead of
//! writing them.

use std::fmt::Write as _;
use std::path::Path;
use std::process::ExitCode;

use clap::Command;
use kapto_config::{DEPLOYMENT_KEYS, DefaultValue};
use kapto_core::ErrorCode;

const HEADER: &str =
    "<!-- Generated by `cargo xtask gen` from the code. Edit the code, not this file. -->\n\n";

/// A generated page: its path from the repository root and how to render it.
pub(crate) struct Page {
    pub(crate) path: &'static str,
    render: fn() -> Result<String, String>,
}

pub(crate) const PAGES: &[Page] = &[
    Page {
        path: "docs/reference/cli.md",
        render: || Ok(cli()),
    },
    Page {
        path: "docs/reference/configuration.md",
        render: || Ok(configuration()),
    },
    Page {
        path: "docs/reference/error-codes.md",
        render: || Ok(error_codes()),
    },
    Page {
        path: "docs/reference/api.md",
        render: api,
    },
    Page {
        path: "docs/reference/openapi.json",
        render: openapi,
    },
    Page {
        path: "ui/src/lib/api-types.ts",
        render: ui_api_types,
    },
    Page {
        path: "docs/reference/episode.md",
        render: || Ok(episode()),
    },
    Page {
        path: "docs/reference/manifest.md",
        render: || Ok(manifest()),
    },
    Page {
        path: "docs/reference/upload-marker.md",
        render: || Ok(upload_marker()),
    },
    Page {
        path: "docs/reference/recording.md",
        render: || Ok(recording()),
    },
    Page {
        path: "docs/reference/struct-layout.md",
        render: || Ok(struct_layout()),
    },
    Page {
        path: "docs/reference/path-layout.md",
        render: || Ok(path_layout()),
    },
    Page {
        path: "docs/reference/package.md",
        render: || Ok(package()),
    },
    Page {
        path: "docs/reference/profiles.md",
        render: || Ok(profiles()),
    },
];

/// Writes every page, or with `check`, lists the ones that are out of date.
pub(crate) fn run(root: &Path, check: bool) -> ExitCode {
    if check {
        let stale = stale_pages(root);
        if stale.is_empty() {
            println!("Generated reference pages are up to date.");
            return ExitCode::SUCCESS;
        }
        for path in stale {
            eprintln!("{path} is out of date. Run `cargo xtask gen` and commit the result.");
        }
        return ExitCode::FAILURE;
    }
    for page in PAGES {
        let path = root.join(page.path);
        let written = (page.render)()
            .and_then(|content| std::fs::write(&path, content).map_err(|error| error.to_string()));
        if let Err(error) = written {
            eprintln!("Can't write {}: {error}", path.display());
            return ExitCode::FAILURE;
        }
        println!("wrote {}", page.path);
    }
    ExitCode::SUCCESS
}

/// Pages whose committed content differs from what the code generates.
pub(crate) fn stale_pages(root: &Path) -> Vec<&'static str> {
    PAGES
        .iter()
        .filter(|page| std::fs::read_to_string(root.join(page.path)).ok() != (page.render)().ok())
        .map(|page| page.path)
        .collect()
}

/// Makes text safe inside a Markdown table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

fn cli() -> String {
    let command = kapto_cli::command();
    let mut page = String::from(HEADER);
    page.push_str("# Command-line reference\n\n");
    let about = command
        .get_about()
        .map(ToString::to_string)
        .unwrap_or_default();
    let _ = writeln!(page, "`{}`: {about}\n", command.get_name());
    page.push_str("## Options for every command\n\n");
    page.push_str("| Option | Description |\n|---|---|\n");
    for arg in command.get_arguments() {
        let _ = writeln!(page, "| {} | {} |", option(arg), help(arg));
    }
    page.push_str("| `-h`, `--help` | Print help |\n");
    page.push_str("| `-V`, `--version` | Print the version (top level only) |\n");
    subcommands(&mut page, &command, command.get_name());
    page
}

fn subcommands(page: &mut String, command: &Command, path: &str) {
    for sub in command.get_subcommands() {
        let path = format!("{path} {}", sub.get_name());
        let about = sub.get_about().map(ToString::to_string).unwrap_or_default();
        let _ = writeln!(page, "\n## `{path}`\n\n{about}.");
        let own: Vec<_> = sub
            .get_arguments()
            .filter(|arg| !arg.is_global_set())
            .collect();
        if !own.is_empty() {
            page.push_str("\n| Option | Description |\n|---|---|\n");
            for arg in own {
                let _ = writeln!(page, "| {} | {} |", option(arg), help(arg));
            }
        }
        subcommands(page, sub, &path);
    }
}

fn option(arg: &clap::Arg) -> String {
    let long = arg
        .get_long()
        .map(|long| format!("--{long}"))
        .unwrap_or_default();
    // A switch takes no value, whatever names clap gives it.
    match arg.get_value_names() {
        Some(names) if !names.is_empty() && arg.get_action().takes_values() => {
            let names: Vec<String> = names.iter().map(|name| format!("<{name}>")).collect();
            format!("`{long} {}`", names.join(" "))
        }
        _ => format!("`{long}`"),
    }
}

fn help(arg: &clap::Arg) -> String {
    cell(&arg.get_help().map(ToString::to_string).unwrap_or_default())
}

fn configuration() -> String {
    let mut page = String::from(HEADER);
    page.push_str(
        "# Configuration reference\n\n\
         Every deployment setting. A value can come from the built-in default,\n\
         `kapto.toml`, an environment variable or a command-line flag, each\n\
         overriding the one before; see\n\
         [Configuration](../concepts/configuration.md).\n",
    );
    for key in DEPLOYMENT_KEYS {
        let default = match key.default {
            DefaultValue::Fixed(text) => format!("`{text}`"),
            DefaultValue::Computed(description) => description.to_owned(),
        };
        let flag = kapto_cli::SETTING_FLAGS
            .iter()
            .find(|(setting, _)| *setting == key.path)
            .map_or_else(|| "none".to_owned(), |(_, flag)| format!("`{flag}`"));
        let _ = write!(
            page,
            "\n## `{path}`\n\n{help}\n\n\
             | | |\n|---|---|\n\
             | Section and name | `[{section}]` `{name}` |\n\
             | Accepts | {accepts} |\n\
             | Default | {default} |\n\
             | Environment variable | `{env}` |\n\
             | Flag | {flag} |\n",
            path = key.path,
            help = key.help,
            section = key.section(),
            name = key.name(),
            accepts = cell(key.value_type.expected()),
            env = key.env_var(),
        );
    }
    page
}

fn error_codes() -> String {
    let mut page = String::from(HEADER);
    page.push_str(
        "# Error codes\n\n\
         Every problem Kapto reports has one of these codes. Codes never change\n\
         between versions. See [Troubleshooting](../troubleshooting/README.md)\n\
         for how to read an error report.\n\n\
         | Code | Problem | What to do |\n|---|---|---|\n",
    );
    for code in ErrorCode::ALL {
        let _ = writeln!(
            page,
            "| `{}` | {} | {} |",
            code.id(),
            cell(code.summary()),
            cell(code.remedy())
        );
    }
    page
}

/// The OpenAPI document, or why it can't be written.
fn openapi_document() -> Result<String, String> {
    kapto_server::api::openapi_json()
        .map_err(|error| format!("the OpenAPI document can't be written: {error}"))
}

fn ui_api_types() -> Result<String, String> {
    let document: serde_json::Value =
        serde_json::from_str(&openapi_document()?).map_err(|error| error.to_string())?;
    Ok(crate::typescript::api_types(
        &document,
        kapto_server::api::API_VERSION,
    ))
}

/// The OpenAPI document itself, for tools; `cargo xtask api-diff` compares
/// it with an earlier one.
fn openapi() -> Result<String, String> {
    Ok(openapi_document()? + "\n")
}

fn api() -> Result<String, String> {
    let document = openapi_document()?;
    let parsed: serde_json::Value =
        serde_json::from_str(&document).map_err(|error| error.to_string())?;
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# API\n\n\
         The local HTTP API of `kapto serve`, on `server.bind`:`server.port`\n\
         (`http://127.0.0.1:7700` by default). Version {}; within a version the\n\
         API only gains endpoints and fields. Errors are JSON with the cause\n\
         `code`, a `message` and a `remedy`, listed in [Error codes](error-codes.md).\n\n\
         Requests that change something take a JSON body, `{{}}` when they have\n\
         no fields, sent with `Content-Type: application/json`. While `server.bind`\n\
         is a loopback address, requests must be addressed to `localhost` or a\n\
         loopback address (`api.host_not_allowed` otherwise).\n\n\
         `/api/events` is a WebSocket: each text message is one `Event` as JSON,\n\
         telling when an episode starts or ends at once and the status at least\n\
         once a second. A page from another site may not open it\n\
         (`api.origin_not_allowed`).\n\n\
         | Method | Path | What it does |\n|---|---|---|\n",
        kapto_server::api::API_VERSION
    );
    if let Some(paths) = parsed["paths"].as_object() {
        for (path, operations) in paths {
            for (method, operation) in operations.as_object().into_iter().flatten() {
                let summary = operation["summary"].as_str().unwrap_or_default();
                let _ = writeln!(
                    page,
                    "| {} | `{path}` | {} |",
                    method.to_uppercase(),
                    cell(summary)
                );
            }
        }
    }
    page.push_str(
        "\nThe full description, with every field: [openapi.json](openapi.json)\n\
         (OpenAPI 3.1). Changes that could break a client within the version are\n\
         found with `cargo xtask api-diff`.\n",
    );
    Ok(page)
}

/// A schema as indented JSON with every object's keys sorted, so the page
/// doesn't change with whether some dependency asks `serde_json` to keep
/// insertion order.
fn schema_json(schema: &schemars::Schema) -> String {
    fn sorted(value: serde_json::Value) -> serde_json::Value {
        match value {
            serde_json::Value::Object(object) => {
                let mut entries: Vec<_> = object.into_iter().collect();
                entries.sort_by(|(a, _), (b, _)| a.cmp(b));
                serde_json::Value::Object(
                    entries
                        .into_iter()
                        .map(|(key, value)| (key, sorted(value)))
                        .collect(),
                )
            }
            serde_json::Value::Array(items) => {
                serde_json::Value::Array(items.into_iter().map(sorted).collect())
            }
            other => other,
        }
    }
    // Back into a schema, which writes its leading keywords (`$schema`,
    // `title`, `description`, …) first, as before.
    schemars::Schema::try_from(sorted(schema.clone().to_value()))
        .and_then(|schema| serde_json::to_string_pretty(&schema))
        .unwrap_or_default()
}

fn episode() -> String {
    use kapto_store::episode::{EPISODE_FILE, Episode, FORMAT, VERSION};

    let schema = schema_json(&schemars::schema_for!(Episode));
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Episode summary format\n\n\
         Every finalised episode folder holds `{EPISODE_FILE}`: what the episode\n\
         is and what happened while it was recorded, readable without opening\n\
         the recording. Format `{FORMAT}`, version {VERSION}. It is listed in\n\
         the [manifest](manifest.md) like every other file.\n\n\
         Message counts follow one rule per stream: every message received is\n\
         either `written` or `dropped_by_us`, and `lost_upstream` counts\n\
         messages that never reached Kapto. What `lost_upstream` means depends\n\
         on `loss_detection`: exact with `sequence`, an estimate with\n\
         `rate_gap`, and always 0 with `undetectable`.\n\n\
         New versions only add fields. A reader that finds a version newer\n\
         than it knows treats the file as unreadable rather than guess.\n\n\
         ## JSON Schema\n\n```json\n{schema}\n```\n"
    );
    page
}

fn manifest() -> String {
    use kapto_store::manifest::{FINALISED_FILE, FORMAT, MANIFEST_FILE, Manifest, VERSION};

    let schema = schema_json(&schemars::schema_for!(Manifest));
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Manifest format\n\n\
         Every finalised episode folder holds `{MANIFEST_FILE}`: each of its\n\
         files with its size and SHA-256. Format `{FORMAT}`, version {VERSION}.\n\n\
         ## Completeness rule\n\n\
         An episode folder is complete only when all of these hold:\n\n\
         1. It contains `{FINALISED_FILE}`. Kapto writes it last, after the\n   \
            manifest, so a folder without it was interrupted.\n\
         2. It contains a `{MANIFEST_FILE}` with format `{FORMAT}`.\n\
         3. The files in the folder and its subfolders, apart from\n   \
            `{MANIFEST_FILE}` and `{FINALISED_FILE}`, are exactly the listed\n   \
            ones, each with its listed size and SHA-256.\n\n\
         Paths use `/` between folders and are sorted. An episode folder holds\n\
         only regular files and folders, no links. New versions only add\n\
         fields; a reader that finds a version newer than it knows treats the\n\
         manifest as unreadable rather than guess.\n\n\
         ## JSON Schema\n\n```json\n{schema}\n```\n"
    );
    page
}

fn upload_marker() -> String {
    use kapto_store::manifest::MANIFEST_FILE;
    use kapto_store::upload_marker::{FORMAT, SUCCESS_FILE, UploadMarker, VERSION};

    let schema = schema_json(&schemars::schema_for!(UploadMarker));
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Upload marker format\n\n\
         Every episode Kapto uploads ends with `{SUCCESS_FILE}` in its folder at\n\
         the destination: each object of the episode there with its size and\n\
         SHA-256. Format `{FORMAT}`, version {VERSION}.\n\n\
         ## Completeness rule\n\n\
         Storage can't make several objects appear at once, so an episode's\n\
         files become visible one by one while it is uploaded. An uploaded\n\
         episode is complete only when all of these hold:\n\n\
         1. Its folder holds `{SUCCESS_FILE}`. Kapto writes it last, once every\n   \
            file is up and verified, so a folder without it is still arriving\n   \
            or was interrupted: leave it alone.\n\
         2. `{SUCCESS_FILE}` has format `{FORMAT}`.\n\
         3. Each object it lists is in the folder with its listed size and\n   \
            SHA-256. The list holds the files of the episode's\n   \
            [manifest](manifest.md) and `{MANIFEST_FILE}` itself.\n\n\
         Kapto writes the marker only if none is there, so an uploaded episode\n\
         is never overwritten; uploading it again finds the marker and stops.\n\
         Paths use `/` between folders and are sorted. New versions only add\n\
         fields; a reader that finds a version newer than it knows treats the\n\
         marker as unreadable rather than guess.\n\n\
         ## JSON Schema\n\n```json\n{schema}\n```\n"
    );
    page
}

/// The start of an episode recorded with a package, profile and task, for
/// the recording format's example.
fn example_start() -> kapto_store::records::EpisodeStart {
    use kapto_store::episode::{OperationMode, PackageIdentity, SessionProfile, SessionTask};
    use kapto_store::records::EpisodeStart;

    EpisodeStart {
        id: "20260305T192345.123Z-1a2b3c4d".into(),
        kapto_version: "0.1.0".into(),
        started_utc_ns: 1_772_700_400_000_000_000,
        package: Some(PackageIdentity {
            id: "arm7".into(),
            version: "0.1.0".into(),
            hash: "9f2c…".into(),
        }),
        profile: Some(SessionProfile {
            id: "lab_ana".into(),
            hash: Some("4e1a…".into()),
            operator: Some("Ana".into()),
            environment: Some("lab 2, bench A".into()),
            mode: Some(OperationMode::Teleoperated),
            tags: vec!["shift-a".into()],
            notes: None,
        }),
        task: Some(SessionTask {
            id: "pick_and_place".into(),
            hash: Some("b07d…".into()),
            name: Some("Pick and place".into()),
            description: None,
            prompt: Some("Pick up the red cube and put it in the bin".into()),
            objects: vec!["red cube".into(), "bin".into()],
            subtasks: vec!["reach".into(), "grasp".into()],
        }),
    }
}

/// The end of a recording of one stream, for the recording format's
/// example.
fn example_end() -> std::collections::BTreeMap<String, String> {
    use kapto_core::{ClockMap, ClockSample, RecvTime};
    use kapto_store::episode::{BufferSummary, LossDetectionKind, StreamSummary};
    use kapto_store::records::EpisodeEnd;

    let clock = ClockMap::new(ClockSample {
        mono: RecvTime::from_nanos(1),
        utc_ns: 1_772_700_400_000_000_000,
        uncertainty: std::time::Duration::from_micros(250),
    });
    let buffers = BufferSummary {
        batches: 6,
        peak_batches: 2,
        memory_bytes: 2_304_000,
    };
    let stream = StreamSummary {
        id: "arm_joints".into(),
        loss_detection: LossDetectionKind::Sequence,
        received: 120_000,
        decoded: 120_000,
        written: 120_000,
        dropped_by_us: 0,
        lost_upstream: 2,
        disconnects: None,
        carried: None,
        pre_roll: None,
        post_roll: None,
    };
    let kept = StreamSummary {
        id: "tf_static".into(),
        loss_detection: LossDetectionKind::Undetectable,
        received: 0,
        decoded: 0,
        written: 0,
        dropped_by_us: 0,
        lost_upstream: 0,
        disconnects: None,
        carried: Some(2),
        pre_roll: None,
        post_roll: None,
    };
    EpisodeEnd::new(1_772_700_460_000_000_000, &clock, &buffers, &[stream, kept]).record()
}

/// The recording page's section on its streams' channels.
fn recording_channels() -> String {
    use kapto_capture::writer::RAW_ENCODING;
    use kapto_decode::{CDR_ENCODING, FIELDS_METADATA, ROS2MSG_ENCODING};

    format!(
        "## Channels\n\n\
         One channel per stream, named after it. Each message is the payload\n\
         exactly as received, its log time the receive time mapped to UTC, and\n\
         its publish time the time its source gave it, as the source has it:\n\
         for a ROS 2 topic, its publisher's timestamp, as rosbag2 writes it.\n\
         Without one, the publish time is the log time. A\n\
         stream with a layout has it as its channel's schema ([Struct\n\
         layout](struct-layout.md), [Layouts by path](path-layout.md)).\n\
         A stream of ROS 2 messages is stored as rosbag2 stores a topic, so\n\
         ROS 2's tools read it: message encoding `{CDR_ENCODING}`, and a schema\n\
         of encoding `{ROS2MSG_ENCODING}` named after the message type (e.g.\n\
         `sensor_msgs/msg/JointState`) whose data is its definition as rosbag2\n\
         writes it; the fields Kapto decodes go in the channel's metadata under\n\
         `{FIELDS_METADATA}`, as a JSON stream's schema holds them. Other\n\
         streams have message encoding `{RAW_ENCODING}` and no schema.\n\n"
    )
}

fn recording() -> String {
    use kapto_capture::writer::{CLOCK_MAP_RECORD, capture_record};
    use kapto_capture::{RingConfig, WriterConfig};
    use kapto_store::records::{CAPTURE_RECORD, EPISODE_RECORD, SUMMARY_RECORD};

    let entries = |record: std::collections::BTreeMap<String, String>| {
        let mut table = String::from("| Name | Value |\n|---|---|\n");
        for (name, value) in record {
            let _ = writeln!(table, "| `{name}` | `{}` |", cell(&value));
        }
        table
    };
    let start = example_start();
    let ring = RingConfig::for_rate(
        2000,
        std::time::Duration::from_millis(500),
        std::time::Duration::from_millis(2),
        256,
        1500,
        1,
    );
    let capture = capture_record(
        &WriterConfig::default(),
        &[("cap-rx-udp-0", &ring)],
        false,
        &std::collections::BTreeMap::from([("meshes/link_1.stl".to_owned(), "5b0e…".to_owned())]),
    );
    let mut page = String::from(HEADER);
    let channels = recording_channels();
    let _ = write!(
        page,
        "# Recording format\n\n\
         Each episode is recorded as one MCAP file, `recording.mcap` in its\n\
         folder. It carries everything it was recorded with, so it can be\n\
         understood without Kapto or the files beside it: tools such as\n\
         `mcap info` and Foxglove show its records as they are.\n\n\
         {channels}\
         ## Metadata records\n\n\
         A record maps names to texts: nested fields have dotted names,\n\
         numbers and switches are written as text, lists as JSON, and absent\n\
         fields are left out. Records are only ever added to, like every\n\
         output format.\n\n\
         ### `{EPISODE_RECORD}`\n\n\
         Written when recording starts, before the first message, so a\n\
         recording cut off part-way still says what it is. The same values as\n\
         [`episode.json`](episode.md), under the same names: the episode's ID,\n\
         the Kapto version that recorded it, when it started, the robot\n\
         package (absent for an `unchecked` episode), and the copies of the\n\
         session profile and task, each with its hash (absent when none was\n\
         chosen).\n\n\
         {}\n\
         ### `{CAPTURE_RECORD}`\n\n\
         Written when recording starts: the settings that shaped the\n\
         recording. `writer.*` is how it is written: compression, chunk size,\n\
         and how often it is put on disk. `buffers.<thread>.*` is each input's\n\
         buffers, named after the thread that receives it. `attach_meshes` is\n\
         whether it carries the package's meshes (`capture.attach_meshes`), and\n\
         `left_out.<path>` the SHA-256 of each package file it doesn't (see\n\
         below), so it can be matched to a package later. Never a secret.\n\n\
         {}\n\
         ### `{SUMMARY_RECORD}`\n\n\
         Written when recording ends, before the file is closed, so a recording\n\
         without it wasn't finished. The same values as `episode.json` then:\n\
         when it ended, how the host's clock behaved (`clock.*`), how close the\n\
         buffers came to full (`buffers.*`), and every stream's counts under its\n\
         name (`streams.<stream>.*`). How long messages waited to be on disk is\n\
         only in `episode.json`: it includes putting the closed file on disk.\n\n\
         {}\n\
         ### `{CLOCK_MAP_RECORD}`\n\n\
         Written when recording ends: every sample of the episode's clock map,\n\
         one entry each, `\"mono_ns utc_ns uncertainty_ns\"` under its\n\
         zero-padded position, so receive times can be mapped to UTC exactly as\n\
         they were.\n\n\
         ## Attachments\n\n\
         Written when recording starts, before the first message: every file of\n\
         the robot package the streams were declared in, exactly as it was when\n\
         capture loaded it, named after its path in the package (`package.toml`,\n\
         `urdf/arm7.urdf`), with its media type (`application/toml`,\n\
         `application/xml`, …). Meshes, and the textures and buffers they load,\n\
         are left out unless `capture.attach_meshes` is on, since a real\n\
         robot's take tens of megabytes per episode: they are files ending in\n\
         {}. An `unchecked` recording,\n\
         whose streams no package declares, carries the stream declarations it\n\
         was recorded from, under their file name.\n",
        entries(start.record()),
        entries(capture),
        entries(example_end()),
        kapto_robot::MESH_EXTENSIONS
            .iter()
            .map(|extension| format!("`.{extension}`"))
            .collect::<Vec<_>>()
            .join(", "),
    );
    page.replace(
        "## Metadata records\n",
        &format!("{}## Metadata records\n", events_section()),
    )
    .replace(
        &format!("### `{CLOCK_MAP_RECORD}`"),
        &format!("{}### `{CLOCK_MAP_RECORD}`", carried_section()),
    )
}

/// The recording page's section on the messages an episode starts with.
fn carried_section() -> String {
    use kapto_capture::writer::{CARRIED_RECORD, carried_record};
    use kapto_store::records::CAPTURE_RECORD;

    let mut table = String::from("| Name | Value |\n|---|---|\n");
    let example = carried_record(&[
        ("tf_static", 1_772_699_800_000_000_000),
        ("tf_static", 1_772_699_800_002_000_000),
    ]);
    for (name, value) in example {
        let _ = writeln!(table, "| `{name}` | `{}` |", cell(&value));
    }
    format!(
        "### `{CARRIED_RECORD}`\n\n\
         Written when recording starts, after `{CAPTURE_RECORD}` and the\n\
         attachments, if the episode starts with messages kept from before it. A stream whose\n\
         messages are kept for late subscribers (a ROS 2 topic subscribed to\n\
         with `durability = \"transient_local\"`, such as `/tf_static`) may\n\
         send them once, long before an episode: capture keeps the newest\n\
         (as many as the subscription's `depth`) and starts every episode\n\
         with them, as that stream's first messages. Each is written as\n\
         received, with its publish time, but at the episode's start as its\n\
         log time, so the episode plays from its start; when it was received\n\
         is here, under its stream's name: a JSON list of receive times in UTC\n\
         nanoseconds, in the order written.\n\n\
         {table}\n"
    )
}

/// The recording page's section on the events channel.
fn events_section() -> String {
    use kapto_store::{EVENTS_CHANNEL, Event, Phase};

    let example = Event {
        kind: "grasp".to_owned(),
        at_utc_ns: 1_772_700_412_500_000_000,
        until_utc_ns: None,
        phase: Phase::Begin,
        id: Some("g1".to_owned()),
        source: "page".to_owned(),
        text: Some("second try".to_owned()),
        attributes: std::collections::BTreeMap::from([("hand".to_owned(), "left".to_owned())]),
    };
    let example = serde_json::to_string_pretty(&example).unwrap_or_default();
    format!(
        "### Events: `{EVENTS_CHANNEL}`\n\n\
         Every recording has one channel of Kapto's own, `{EVENTS_CHANNEL}`: what\n\
         happened while it was recorded, at a moment or over a stretch. An episode\n\
         started or ended, a stream lost messages, an action began or ended, an\n\
         operator noted something. Each message is one event as JSON (message\n\
         encoding `json`, schema encoding `jsonschema`), its log time the event's\n\
         moment on the same clock as the streams' messages, so it lines up with\n\
         what the robot sent. Events are written between the streams' batches, so\n\
         an event can come a little after messages received later than it in the\n\
         file: order them by their moment. A stream's ID never holds a dot, so no\n\
         stream is named like a channel of Kapto's own (`kapto.…`).\n\n\
         - `kind`: what happened, lowercase words joined by dots (`grasp`,\n\
           `subtask.reach`); kinds beginning `kapto.` are Kapto's own.\n\
         - `phase`: `moment` (left out), or `begin` and `end` of a stretch, paired\n\
           by the same `kind` and `id` and sent as each happens, or `stretch`, a\n\
           whole stretch told at once, from `at_utc_ns` to `until_utc_ns`.\n\
         - `source`: `kapto`, `page`, `api`, `cli` or `robot:<stream>`.\n\
         - `text` and `attributes`: what someone said about it, if anything.\n\n\
         Kapto keeps these of its own during an episode, from source `kapto`,\n\
         saying when in it a stream had trouble, which its totals don't:\n\n\
         | Kind | When | Attributes |\n\
         |---|---|---|\n\
         | `kapto.stream_lost` | A stream lost messages, at most once a second | `stream`, `lost_upstream`, `dropped_by_us`: how many since the last |\n\
         | `kapto.stream_silent` | A stream sent nothing for 2 s | `stream` |\n\
         | `kapto.stream_back` | A silent stream sent again | `stream` |\n\n\
         Fields are only ever added, like every output format.\n\n\
         ```json\n{example}\n```\n\n\
         The channel's schema:\n\n\
         ```json\n{}\n```\n\n",
        schema_json(&schemars::schema_for!(Event))
    )
}

fn struct_layout() -> String {
    use kapto_decode::{Endianness, FieldSpec, STRUCT_ENCODING, ScalarType, StructLayout};

    let example = StructLayout {
        fields: vec![
            FieldSpec::new("sequence", ScalarType::U32, 0),
            FieldSpec {
                count: 7,
                endianness: Endianness::Big,
                scale: Some(0.001),
                unit: Some("rad".to_owned()),
                ..FieldSpec::new("joint_positions", ScalarType::I32, 4)
            },
        ],
    };
    let json = example.to_schema_json_pretty();
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Struct layout format\n\n\
         A stream whose messages have a fixed binary layout declares it in\n\
         `streams.toml` (see [Configuration](../concepts/configuration.md)), and\n\
         every recording stores it, so the recording can be decoded without the\n\
         configuration it was made with.\n\n\
         ## In a recording\n\n\
         The stream's MCAP channel has message encoding `{STRUCT_ENCODING}`: each\n\
         message is the payload exactly as received. The channel's schema has\n\
         encoding `{STRUCT_ENCODING}`, the stream's name as its name, and the\n\
         layout as JSON as its data. Streams without a layout are stored with\n\
         message encoding `kapto.raw` and no schema.\n\n\
         ```json\n{json}\n```\n\n\
         Every key is always written. A reader requires `name`, `type` and\n\
         `offset`; `count` defaults to 1, `byte_order` to `little`, and `scale`\n\
         and `unit` to none.\n\n\
         ## Fields\n\n\
         | Key | Meaning |\n|---|---|\n\
         | `name` | Lowercase letters, digits and underscores, starting with a letter; unique in the layout. |\n\
         | `type` | One of the types below. |\n\
         | `offset` | Byte offset of the first value in the message. |\n\
         | `count` | Number of values one after another: 1 for a single value, more for an array. |\n\
         | `byte_order` | `little` (least significant byte first) or `big`. |\n\
         | `scale` | Multiplier applied to each value, e.g. 0.001 for a value sent in thousandths. Scaled values are decimals. Not allowed on `bool`. |\n\
         | `unit` | The unit of the (scaled) value, e.g. `rad`. |\n\n\
         Every field must end within 65,507 bytes, the largest UDP message.\n\
         Fields may overlap. Bytes no field covers are ignored, and a message\n\
         shorter than the end of the last field is not decoded (it is still\n\
         recorded).\n\n\
         ## Types\n\n| Type | Bytes |\n|---|---|\n"
    );
    for ty in ScalarType::ALL {
        let _ = writeln!(page, "| `{}` | {} |", ty.name(), ty.size());
    }
    page.push_str(
        "\nIntegers decode as integers unless scaled, so 64-bit values keep every\n\
         digit. A `bool` is one byte: 0 is false, anything else true.\n",
    );
    page
}

fn path_layout() -> String {
    use kapto_decode::path::CONVERSIONS;
    use kapto_decode::{JSON_ENCODING, MSGPACK_ENCODING, PathField, PathLayout, ScalarType};

    let example = PathLayout {
        format: kapto_decode::PathFormat::Json,
        fields: vec![
            PathField::new("sequence", "header.seq", ScalarType::U32),
            PathField {
                count: 7,
                unit: Some("rad".to_owned()),
                ..PathField::new("joint_positions", "joints.position", ScalarType::F64)
            },
        ],
    };
    let json = example.to_schema_json_pretty();
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Layouts by path: JSON, MessagePack and ROS 2\n\n\
         A stream whose messages are JSON, MessagePack or ROS 2 messages\n\
         declares, in `streams.toml`, a decoder of `kind = \"json\"`,\n\
         `kind = \"msgpack\"` or `kind = \"cdr\"` whose fields each give a\n\
         `path` through the message (see\n\
         [Configuration](../concepts/configuration.md)). Every recording stores\n\
         the layout, so the recording can be decoded without the configuration\n\
         it was made with.\n\n\
         ```toml\n\
         [streams.arm.decoder]\n\
         kind = \"json\"\n\n\
         [[streams.arm.decoder.fields]]\n\
         name = \"joint_positions\"\n\
         type = \"f64\"\n\
         path = \"joints.position\"\n\
         count = 7\n\
         unit = \"rad\"\n\
         ```\n\n\
         ## Paths\n\n\
         A path is keys separated by dots, with `[n]` for the n-th element of an\n\
         array, counted from 0: `joints.position[2]`, `state.pose.x`, `[0].id`.\n\
         A key is any text without `.`, `[` or `]`; in MessagePack, a key that\n\
         is a number matches its digits. A field with `count` above 1 names an\n\
         array and takes its first `count` elements.\n\n\
         An element can also be found by name: `position[name=shoulder]` is\n\
         the element of `position` at the place where the array `name` beside\n\
         it holds `shoulder`, as a ROS 2 `JointState` lists its joints. The\n\
         field is then the same joint whatever order the robot sends its\n\
         joints in; a message without the name is missing the field, never\n\
         given another joint's value. A path looks up one name, for one value\n\
         (`count` 1): declare a field for each joint. Each such field reads\n\
         the message twice, once to find the name and once for the value.\n\n\
         ## Values\n\n\
         Each value is converted to the field's `type` by the same rules in\n\
         every format, then multiplied by its `scale` if it has one:\n\n\
         | Type | Accepts |\n|---|---|\n"
    );
    for (types, accepts) in CONVERSIONS {
        let _ = writeln!(page, "| {types} | {accepts} |");
    }
    let _ = write!(
        page,
        "\nA path that isn't in the message, or a name it doesn't hold, leaves\n\
         that field missing and the others decoded: a topic two publishers\n\
         share, such as an arm's and a gripper's joint states, gives each\n\
         field from the messages that have it. The live view and the replay\n\
         keep a missing value's last one, the quality checks have no value for\n\
         it at that time, and `kapto decode` leaves its cell empty; it is never\n\
         read as 0. A message with none of its fields isn't decoded.\n\n\
         Text, `null`, maps and arrays where a value is expected, or a value\n\
         outside its type's range, leave the message undecoded; it is still\n\
         recorded exactly as it arrived. So is a message that isn't valid JSON\n\
         or MessagePack.\n\n\
         ## In a recording\n\n\
         The stream's MCAP channel has message encoding `{JSON_ENCODING}` or\n\
         `{MSGPACK_ENCODING}`: each message is the payload exactly as received.\n\
         The channel's schema has the same encoding, the stream's name as its\n\
         name, and the layout as JSON as its data:\n\n\
         ```json\n{json}\n```\n\n\
         Every key is always written. A reader requires `name`, `type` and\n\
         `path`; `count` defaults to 1, and `scale` and `unit` to none. The\n\
         keys mean the same as in a [struct layout](struct-layout.md), with\n\
         `path` in place of `offset` and `byte_order`.\n\n"
    );
    page.push_str(&ros2_messages());
    page
}

/// The section of the path layout page on ROS 2 messages.
fn ros2_messages() -> String {
    use kapto_decode::{CDR_ENCODING, FIELDS_METADATA, ROS2MSG_ENCODING, TOPIC_METADATA};

    format!(
        "## ROS 2 messages\n\n\
         A stream of ROS 2 messages, serialised as ROS 2 does (CDR), names\n\
         their type too, and finds fields by path through the message as its\n\
         definition lays it out: `header.stamp.sec`, `position[2]`.\n\n\
         ```toml\n\
         [streams.joints.decoder]\n\
         kind = \"cdr\"\n\
         type = \"sensor_msgs/msg/JointState\"\n\n\
         [[streams.joints.decoder.fields]]\n\
         name = \"position\"\n\
         type = \"f64\"\n\
         path = \"position\"\n\
         count = 7\n\
         unit = \"rad\"\n\
         ```\n\n\
         The type's definition is put together from `.msg` files in the `msg/`\n\
         folder beside `streams.toml`, laid out as ROS 2 installs them: the\n\
         type's own, `msg/sensor_msgs/msg/JointState.msg`, and that of every\n\
         type it uses (`msg/std_msgs/msg/Header.msg`,\n\
         `msg/builtin_interfaces/msg/Time.msg`), copied from a ROS 2\n\
         installation's `share` folder. A file not in the package is looked\n\
         for in the ROS 2 installation Kapto runs in, in each `share` folder of\n\
         `AMENT_PREFIX_PATH` in turn. A missing file is\n\
         `decoder.msg_not_found`, naming it and the type that uses it. A\n\
         recording carries every `.msg` file its streams use, at the same place\n\
         beside `streams.toml`: the package's among its files, and those read\n\
         from the installation besides, so it reads back without either.\n\n\
         A ROS 2 topic (`ros2 = {{ topic, type }}`) is decoded the same way;\n\
         its decoder has the topic's `type`, and needs none of its own.\n\n\
         In a recording the stream is stored as rosbag2 stores a topic, so\n\
         ROS 2's tools and Foxglove read it: message encoding\n\
         `{CDR_ENCODING}`, and a schema of encoding `{ROS2MSG_ENCODING}` named\n\
         after the type (`sensor_msgs/msg/JointState`) whose data is its\n\
         definition as rosbag2 writes it: the type's own `.msg` file, then each\n\
         type it uses, once, depth first, each type's in alphabetical order,\n\
         after a line of 80 `=` and `MSG: package/Type`. Kapto's fields go in\n\
         the channel's metadata under `{FIELDS_METADATA}`, as the JSON above. A\n\
         channel of this encoding without them, recorded by another tool,\n\
         decodes into no values.\n\n\
         A topic is stored the same way, with or without a decoder. Its\n\
         channel is named after the stream, as every channel is, and the topic\n\
         it was received on is in the channel's metadata under\n\
         `{TOPIC_METADATA}`. `ros2 bag info` and Foxglove read the recording;\n\
         rosbag2 doesn't replay or convert it, as it refuses a bag whose\n\
         channels have more than one encoding, and Kapto's own events channel\n\
         is JSON. `kapto export rosbag2` writes an episode's topics as a bag of\n\
         their own (one MCAP file, profile `ros2`): each channel named after\n\
         its topic, with its schema, and each message with its sequence and\n\
         both times as recorded, which `ros2 bag play` replays.\n"
    )
}

fn profiles() -> String {
    use kapto_config::{
        DEFAULT_KINDS, EVENT_KIND_KEYS, EVENTS_EXAMPLE, EVENTS_FILE, FileKey, PROFILE_EXAMPLE,
        PROFILE_KEYS, PROFILES_DIR, SUBTASK_KINDS, TASK_EXAMPLE, TASK_KEYS, TASKS_DIR,
    };

    let keys = |page: &mut String, keys: &[FileKey]| {
        page.push_str("| Key | Required | Meaning |\n|---|---|---|\n");
        for key in keys {
            let required = if key.required { "yes" } else { "no" };
            let _ = writeln!(page, "| `{}` | {required} | {} |", key.name, cell(key.help));
        }
    };
    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Profiles and tasks\n\n\
         A session setup can be saved in the configuration folder, the folder of\n\
         `kapto.toml`, so the same recordings are set up the same way every time:\n\
         a **profile** says with which robot, by whom, where and how it is\n\
         recorded, and a **task** what the robot is asked to do. The two are\n\
         independent: each episode is recorded with a profile and a task chosen\n\
         separately, so operators and places change without touching the tasks,\n\
         and every profile can record every task. Each is a TOML file known by its name without\n\
         `.toml`, which must be an ID: lowercase letters, digits and underscores,\n\
         starting with a letter.\n\n\
         Every text must say something: blank values and placeholders such as\n\
         `na`, `n/a`, `none`, `-` or `tbd` are refused, since they would be\n\
         frozen into every episode recorded with them.\n\n\
         ## Profiles: `{PROFILES_DIR}/<id>.toml`\n\n\
         ```toml\n# {PROFILES_DIR}/lab_ana.toml\n{PROFILE_EXAMPLE}```\n\n"
    );
    keys(&mut page, &PROFILE_KEYS);
    let _ = write!(
        page,
        "\n## Tasks: `{TASKS_DIR}/<id>.toml`\n\n\
         ```toml\n# {TASKS_DIR}/pick_and_place.toml\n{TASK_EXAMPLE}```\n\n"
    );
    keys(&mut page, &TASK_KEYS);
    let defaults: Vec<String> = DEFAULT_KINDS
        .iter()
        .map(|(kind, _, stretch)| {
            if *stretch {
                format!("`{kind}` (a stretch)")
            } else {
                format!("`{kind}`")
            }
        })
        .collect();
    let _ = write!(
        page,
        "\n## Event kinds: `{EVENTS_FILE}`\n\n\
         The kinds of [events](recording.md#events-kaptoevents) people and programs\n\
         may send, beside Kapto's own: what each is called, its colour on the\n\
         timeline, and whether it is usually a stretch, begun and ended, rather\n\
         than a moment, which is how the page offers it. Each kind is a table\n\
         under `kinds`, named by the kind: lowercase words joined by dots, not\n\
         beginning `kapto.` (Kapto's own) or `{SUBTASK_KINDS}` (the tasks').\n\n\
         ```toml\n# {EVENTS_FILE}\n{EVENTS_EXAMPLE}```\n\n"
    );
    keys(&mut page, &EVENT_KIND_KEYS);
    let _ = write!(
        page,
        "\nWithout the file, {} may be sent. Each task's subtasks are kinds\n\
         too, whatever the file says: `{SUBTASK_KINDS}` then the subtask in\n\
         lowercase, anything but letters and digits as underscores (`Pick up`\n\
         is `{SUBTASK_KINDS}pick_up`), each a stretch. A file with a problem is\n\
         reported, and the kinds there are without it are used meanwhile.\n",
        defaults.join(", ")
    );
    page
}

/// The package page's section on `layout.toml`.
fn layout_section() -> String {
    use kapto_config::{
        LAYOUT_COLUMN_KEYS, LAYOUT_EXAMPLE, LAYOUT_FILE, LAYOUT_PANEL_KEYS, LAYOUTS_FOLDER,
        MAX_PANELS,
    };
    let mut page = String::new();
    let _ = write!(
        page,
        "\n## `{LAYOUT_FILE}`\n\n\
         How the live view and replays are arranged: columns side by side, each a\n\
         stack of panels, the timeline always under them. Below a width of 70rem\n\
         the columns stack, in order. A package without one is shown with a layout\n\
         made from what it declares: the robot on the left if a joint of it moves;\n\
         on the right each camera, a plot per group of roles (the joints' positions\n\
         first), a plot per stream of the fields no role covers (but its counters\n\
         and clocks, which only ever climb); the streams' health is beside the view\n\
         in the console. At most {MAX_PANELS} panels: beyond, the page can't\n\
         keep its frame rate. A panel naming a stream, field or role the package\n\
         doesn't have is shown as a placeholder saying what is missing. A layout\n\
         saved as the package's default, `{LAYOUTS_FOLDER}/<package id>.toml` in the\n\
         configuration folder (`PUT /api/layout`), comes before the package's own,\n\
         in every browser, until it is removed (`DELETE /api/layout`).\n\n\
         ```toml\n{LAYOUT_EXAMPLE}```\n\n\
         Each `[[columns]]` table:\n\n\
         | Key | Required | Meaning |\n|---|---|---|\n"
    );
    for key in LAYOUT_COLUMN_KEYS {
        let required = if key.required { "yes" } else { "no" };
        let _ = writeln!(page, "| `{}` | {required} | {} |", key.name, cell(key.help));
    }
    page.push_str("\nEach panel:\n\n| Key | Required | Meaning |\n|---|---|---|\n");
    for key in LAYOUT_PANEL_KEYS {
        let required = if key.required { "yes" } else { "no" };
        let _ = writeln!(page, "| `{}` | {required} | {} |", key.name, cell(key.help));
    }
    page
}

fn package() -> String {
    use kapto_config::{PACKAGE_FILE, PACKAGE_KEYS, QA_FILE, QA_KEYS};

    let mut page = String::from(HEADER);
    let _ = write!(
        page,
        "# Robot package format\n\n\
         A robot package is a folder that describes one robot to Kapto: its\n\
         `{PACKAGE_FILE}`, the robot's URDF and meshes, what it sends\n\
         (`streams.toml`, see [Configuration](../concepts/configuration.md)) and\n\
         which decoded value drives which joint (`mapping.toml`). Kapto finds the\n\
         packages in the folders of `paths.packages`; `kapto package list` shows\n\
         them and `kapto package show` one of them.\n\n\
         ```toml\n{}```\n\n\
         ## `{PACKAGE_FILE}`\n\n\
         | Key | Required | Meaning |\n|---|---|---|\n",
        include_str!("../../../packages/arm7/package.toml")
    );
    for key in PACKAGE_KEYS {
        let required = if key.required { "yes" } else { "no" };
        let _ = writeln!(page, "| `{}` | {required} | {} |", key.name, cell(key.help));
    }
    page.push_str("\nPaths are relative to the package folder and may not lead out of it.\n\n");
    let _ = write!(
        page,
        "## `{QA_FILE}`\n\n\
         Which quality checks run on the episodes recorded with the package, and\n\
         their thresholds. Each check's settings are in the table named after its\n\
         ID; a check left out runs with its defaults, and so does every check of a\n\
         package without `{QA_FILE}`. Every result records `qa_params_version`, so\n\
         results computed with different settings aren't taken for alike. Every\n\
         recording carries the `{QA_FILE}` it was recorded with, and its episode\n\
         is checked with that copy, so editing the package later never changes\n\
         an episode's results.\n\n\
         ```toml\n{}```\n\n\
         | Key | Required | Meaning |\n|---|---|---|\n",
        include_str!("../../../packages/arm7/qa.toml")
    );
    for key in QA_KEYS {
        let required = if key.required { "yes" } else { "no" };
        let _ = writeln!(page, "| `{}` | {required} | {} |", key.name, cell(key.help));
    }
    page.push_str(&layout_section());
    page.push_str(
        "\n## Identity\n\n\
         A version of a package is identified by its `id` and `version`, and by\n\
         its content hash, which changes whenever any of its files does, even if\n\
         the version wasn't raised. The hash is SHA-256 over one line per file,\n\
         `<SHA-256 of the file>  <path>`, with paths relative to the package\n\
         folder and separated by `/`, sorted in byte order, each line ending in a\n\
         newline. Files and folders whose names start with a dot are left out, so\n\
         a `.git` folder or an editor's leftovers don't change it. It is what\n\
         `sha256sum` gives, so it can be checked without Kapto:\n\n\
         ```sh\n\
         cd packages/arm7\n\
         find . -type f ! -path '*/.*' | sed 's|^\\./||' | LC_ALL=C sort | xargs sha256sum | sha256sum\n\
         ```\n\n\
         A package holds only plain files and folders with UTF-8 names: Kapto\n\
         refuses symbolic links rather than follow them out of the package.\n\n\
         ## Lint rules\n\n\
         `kapto package lint` loads a package the way Kapto does to run it and\n\
         reports every problem with its file and line where it has them, and\n\
         what to do. An error means Kapto can't use the package; a warning that\n\
         it can, with something missing. The command fails on errors only;\n\
         `--format json` gives the same report for tools.\n\n\
         | Code | Severity | Checks |\n|---|---|---|\n",
    );
    for rule in kapto_robot::RULES {
        let severity = match rule.severity {
            kapto_robot::Severity::Error => "error",
            kapto_robot::Severity::Warning => "warning",
        };
        let _ = writeln!(
            page,
            "| `{}` | {severity} | {} |",
            rule.code.id(),
            cell(rule.checks)
        );
    }
    page.push_str(
        "\nA problem in `package.toml` stops the checks after it, since it names\n\
         the other files. A problem in one of those stops only the checks that\n\
         need that file; checking the mapping needs all three.\n",
    );
    page
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_switch_is_shown_without_a_value_and_an_option_with_its_own() {
        let switch = clap::Arg::new("unattended")
            .long("unattended")
            .value_name("UNATTENDED")
            .action(clap::ArgAction::SetTrue);
        assert_eq!(option(&switch), "`--unattended`");
        let valued = clap::Arg::new("port").long("port").value_name("PORT");
        assert_eq!(option(&valued), "`--port <PORT>`");
    }

    #[test]
    fn every_page_says_it_is_generated() {
        // JSON can't hold a comment; the API page, which links the OpenAPI
        // document, says it is generated.
        for page in PAGES {
            let extension = Path::new(page.path).extension();
            if extension.is_some_and(|extension| extension == "json") {
                continue;
            }
            let typescript = extension.is_some_and(|extension| extension == "ts");
            let header = if typescript {
                crate::typescript::HEADER
            } else {
                HEADER
            };
            assert!(
                (page.render)().unwrap().starts_with(header),
                "{}",
                page.path
            );
        }
    }

    #[test]
    fn error_code_page_lists_every_code() {
        let page = error_codes();
        for code in ErrorCode::ALL {
            assert!(page.contains(&format!("| `{}` |", code.id())), "{code}");
        }
    }

    #[test]
    fn configuration_page_documents_every_setting_with_its_variable_and_flag() {
        let page = configuration();
        for key in DEPLOYMENT_KEYS {
            assert!(page.contains(&format!("## `{}`", key.path)));
            assert!(page.contains(&format!("`{}`", key.env_var())));
        }
        assert!(page.contains("| Flag | `--port` |"));
        assert!(page.contains("| Default | `7700` |"));
    }

    #[test]
    fn cli_page_lists_global_options_and_every_command() {
        let page = cli();
        assert!(page.contains("| `--config <FILE>` |"));
        assert!(page.contains("## `kapto config validate`"));
        assert!(page.contains("## `kapto config show`"));
    }

    #[test]
    fn episode_page_includes_the_schema_of_every_stream_counter() {
        let page = episode();
        for field in [
            "received",
            "decoded",
            "written",
            "dropped_by_us",
            "lost_upstream",
        ] {
            assert!(page.contains(&format!("\"{field}\"")), "{field}");
        }
    }

    #[test]
    fn manifest_page_includes_the_schema_of_every_field() {
        let page = manifest();
        for field in [
            "format", "version", "episode", "files", "path", "bytes", "sha256",
        ] {
            assert!(page.contains(&format!("\"{field}\"")), "{field}");
        }
    }

    #[test]
    fn upload_marker_page_includes_the_schema_of_every_field() {
        let page = upload_marker();
        for field in [
            "format",
            "version",
            "episode",
            "robot",
            "kapto_version",
            "uploaded_utc_ns",
            "files",
            "sha256",
        ] {
            assert!(page.contains(&format!("\"{field}\"")), "{field}");
        }
    }

    #[test]
    fn table_cells_escape_pipes_and_newlines() {
        assert_eq!(cell("a|b\nc"), "a\\|b c");
    }

    #[test]
    fn committed_pages_match_the_code() {
        let root = crate::repo_root();
        assert_eq!(
            stale_pages(&root),
            Vec::<&str>::new(),
            "run `cargo xtask gen`"
        );
    }
}
